import sys


def main():
    flags = set()
    args = []
    for arg in sys.argv[1:]:
        if arg.startswith("-"):
            flags.update(arg.lstrip("-"))
        else:
            args.append(arg)

    if not args or args[-1] == "-":
        fpath = None
    else:
        fpath = args[-1]

    with open(fpath, "rb") as f:
        raw = f.read() if fpath is not None else sys.stdin.buffer.read()

    char_count = len(raw)
    line_count = raw.count(b"\n")
    # A final line with no trailing newline still counts as a line
    if raw and not raw.endswith(b"\n"):
        line_count += 1

    text = raw.decode("utf-8", errors="replace")
    word_count = len(text.split())

    order = ["l", "w", "c"]
    show = [f for f in order if f in flags] if flags else order

    vals = {"l": line_count, "w": word_count, "c": char_count}
    print(*(vals[f] for f in show))


if __name__ == "__main__":
    main()

